1	import { Router, type IRouter } from "express";
2	import { desc, eq, or, and, sql, inArray } from "drizzle-orm";
3	import { clerkClient } from "@clerk/express";
4	import { db, directMessagesTable, notificationsTable, userProfilesTable } from "@workspace/db";
5	import { requireAuth, getCurrentUserId } from "../lib/auth";
6	import { socketEmit, dmRoom, getPresence } from "../lib/socket";
7	
8	const router: IRouter = Router();
9	
10	// Player inbox isolation: facility-scoped DMs belong to the owner inbox
11	// (/messages/owner-inbox), not the personal /dm/* threads. `IS DISTINCT FROM`
12	// is the NULL-safe form of `!=` so untyped DMs (most personal conversations)
13	// still match.
14	const notFacilityContext = sql`${directMessagesTable.contextType} IS DISTINCT FROM 'facility'`;
15	
16	// Allowlist of contextType values legitimate /dm/send callers ever produce
17	// (chat-bubble + court / tournament / booking / game pages). Anything outside
18	// this set — including 'facility', which has its own route — gets coerced
19	// to null so a malicious client cannot smuggle data past notFacilityContext.
20	const ALLOWED_DM_CONTEXT_TYPES = new Set(["game", "court", "tournament", "booking"]);
21	function sanitizeContextType(raw: unknown): string | null {
22	  return typeof raw === "string" && ALLOWED_DM_CONTEXT_TYPES.has(raw) ? raw : null;
23	}
24	function sanitizeContextId(raw: unknown): number | null {
25	  const n = typeof raw === "number" ? raw : typeof raw === "string" ? Number(raw) : NaN;
26	  return Number.isInteger(n) && n > 0 ? n : null;
27	}
28	
29	function formatMsg(r: typeof directMessagesTable.$inferSelect) {
30	  return {
31	    ...r,
32	    createdAt: r.createdAt.toISOString(),
33	    readAt: r.readAt ? r.readAt.toISOString() : null,
34	  };
35	}
36	
37	// GET /dm/threads — list my conversations, grouped by "other user"
38	router.get("/dm/threads", requireAuth, async (req, res): Promise<void> => {
39	  const userId = getCurrentUserId(req)!;
40	
41	  const rows = await db.select().from(directMessagesTable)
42	    .where(and(
43	      or(eq(directMessagesTable.senderUserId, userId), eq(directMessagesTable.recipientUserId, userId)),
44	      notFacilityContext,
45	    ))
46	    .orderBy(desc(directMessagesTable.createdAt));
47	
48	  const threadMap = new Map<string, {
49	    otherUserId: string;
50	    otherUserName: string;
51	    lastMessage: ReturnType<typeof formatMsg>;
52	    unread: number;
53	  }>();
54	
55	  for (const r of rows) {
56	    const otherUserId = r.senderUserId === userId ? r.recipientUserId : r.senderUserId;
57	    const existing = threadMap.get(otherUserId);
58	    const isIncoming = r.recipientUserId === userId;
59	    const isUnread = isIncoming && !r.readAt;
60	    if (!existing) {
61	      threadMap.set(otherUserId, {
62	        otherUserId,
63	        otherUserName: r.senderUserId === userId ? "—" : r.senderName,
64	        lastMessage: formatMsg(r),
65	        unread: isUnread ? 1 : 0,
66	      });
67	    } else if (isUnread) {
68	      existing.unread += 1;
69	    }
70	  }
71	
72	  // Fill in names for threads where the latest message is from me
73	  for (const thread of threadMap.values()) {
74	    if (thread.otherUserName === "—") {
75	      const fromOther = rows.find(r => r.senderUserId === thread.otherUserId);
76	      if (fromOther) thread.otherUserName = fromOther.senderName;
77	      else thread.otherUserName = "Vartotojas";
78	    }
79	  }
80	
81	  // Fetch avatars for all other users from userProfilesTable
82	  const otherIds = [...threadMap.keys()];
83	  const imageMap = new Map<string, string | null>();
84	  if (otherIds.length > 0) {
85	    const profiles = await db
86	      .select({ userId: userProfilesTable.userId, imageUrl: userProfilesTable.imageUrl })
87	      .from(userProfilesTable)
88	      .where(inArray(userProfilesTable.userId, otherIds));
89	    for (const p of profiles) imageMap.set(p.userId, p.imageUrl);
90	  }
91	
92	  const threads = [...threadMap.values()].map(t => ({
93	    ...t,
94	    otherUserImageUrl: imageMap.get(t.otherUserId) ?? null,
95	  }));
96	
97	  res.json(threads);
98	});
99	
100	// GET /dm/thread/:otherUserId — all messages between me and otherUserId
101	router.get("/dm/thread/:otherUserId", requireAuth, async (req, res): Promise<void> => {
102	  const userId = getCurrentUserId(req)!;
103	  const otherUserId = String(req.params.otherUserId);
104	
105	  const rows = await db.select().from(directMessagesTable)
106	    .where(and(
107	      or(
108	        and(eq(directMessagesTable.senderUserId, userId), eq(directMessagesTable.recipientUserId, otherUserId)),
109	        and(eq(directMessagesTable.senderUserId, otherUserId), eq(directMessagesTable.recipientUserId, userId)),
110	      ),
111	      notFacilityContext,
112	    ))
113	    .orderBy(directMessagesTable.createdAt);
114	
115	  // Mark incoming messages as read and signal all of the user's tabs to
116	  // refresh their unread badge immediately (Test 3: multi-tab sync).
117	  const updated = await db.update(directMessagesTable).set({ readAt: new Date() })
118	    .where(and(
119	      eq(directMessagesTable.senderUserId, otherUserId),
120	      eq(directMessagesTable.recipientUserId, userId),
121	      sql`${directMessagesTable.readAt} IS NULL`,
122	      notFacilityContext,
123	    )).returning({ id: directMessagesTable.id });
124	
125	  if (updated.length > 0) {
126	    socketEmit(`inbox_${userId}`, "unread_update", {});
127	  }
128	
129	  res.json(rows.map(formatMsg));
130	});
131	
132	// POST /dm/send — send a direct message
133	router.post("/dm/send", requireAuth, async (req, res): Promise<void> => {
134	  const userId = getCurrentUserId(req)!;
135	  const { recipientUserId, body, contextType, contextId } = req.body ?? {};
136	  if (!recipientUserId || !body) {
137	    res.status(400).json({ error: "recipientUserId, body required" }); return;
138	  }
139	
140	  // Resolve sender display name from Clerk — never trust client-supplied
141	  // senderName, otherwise a malicious caller can DM anyone under another
142	  // user's name. Mirrors routes/messages.ts:209.
143	  let senderName = "Vartotojas";
144	  try {
145	    const clerkUser = await clerkClient.users.getUser(userId);
146	    senderName = [clerkUser.firstName, clerkUser.lastName].filter(Boolean).join(" ") || "Vartotojas";
147	  } catch {
148	    // Clerk unavailable (e.g. no CLERK_SECRET_KEY in dev) — fall back to the default.
149	  }
150	
151	  // contextType/contextId come from the client; the allowlist below is the
152	  // single point of enforcement for "/dm is not for facility messages". If
153	  // this is loosened, the /dm/threads + /dm/unread-count filters become
154	  // bypassable via the live socket path.
155	  const safeContextType = sanitizeContextType(contextType);
156	  const safeContextId = safeContextType ? sanitizeContextId(contextId) : null;
157	
158	  const [msg] = await db.insert(directMessagesTable).values({
159	    senderUserId: userId,
160	    senderName,
161	    recipientUserId,
162	    body,
163	    contextType: safeContextType,
164	    contextId: safeContextId,
165	  }).returning();
166	
167	  // Notification for recipient
168	  await db.insert(notificationsTable).values({
169	    userId: recipientUserId,
170	    type: "message",
171	    title: `Nauja žinutė nuo ${senderName}`,
172	    body: body.length > 100 ? body.slice(0, 97) + "…" : body,
173	    link: `/messages?u=${userId}`,
174	  }).catch(() => {});
175	
176	  // Real-time: push to the shared DM room and trigger an unread badge refresh
177	  const formatted = formatMsg(msg);
178	  socketEmit(dmRoom(userId, recipientUserId), "new_message", { type: "dm", message: formatted });
179	  socketEmit(`inbox_${recipientUserId}`, "unread_update", {});
180	
181	  res.status(201).json(formatted);
182	});
183	
184	// GET /dm/unread-count
185	router.get("/dm/unread-count", requireAuth, async (req, res): Promise<void> => {
186	  const userId = getCurrentUserId(req)!;
187	  const [row] = await db.select({ count: sql<number>`count(*)` }).from(directMessagesTable)
188	    .where(and(
189	      eq(directMessagesTable.recipientUserId, userId),
190	      sql`${directMessagesTable.readAt} IS NULL`,
191	      notFacilityContext,
192	    ));
193	  res.json({ count: Number(row?.count ?? 0) });
194	});
195	
196	// GET /dm/presence?userIds=id1,id2
197	router.get("/dm/presence", requireAuth, (req, res): void => {
198	  const ids = String(req.query.userIds ?? "")
199	    .split(",")
200	    .map(s => s.trim())
201	    .filter(Boolean)
202	    .slice(0, 50);
203	  res.json(getPresence(ids));
204	});
205	
206	export default router;
