37	function getCourtScope(location: string): { facilityId: number; courtId: number } | null {
38	  const m = location.match(/^\/owner\/facility\/(\d+)\/court\/(\d+)(?:\/|$)/);
39	  if (!m) return null;
40	  return { facilityId: Number(m[1]), courtId: Number(m[2]) };
41	}
