156	// ── Shared row ────────────────────────────────────────────────────────────────
157	
158	function NavLink({
159	  item,
160	  active,
161	  onNavigate,
162	  accent = false,
163	}: {
164	  item: NavItem;
165	  active: boolean;
166	  onNavigate: (href: string) => void;
167	  accent?: boolean;
168	}) {
169	  return (
170	    <a
171	      href={`${BASE_URL}${item.href}`}
172	      onClick={(e) => {
173	        if (e.metaKey || e.ctrlKey || e.shiftKey || e.altKey || e.button !== 0) return;
174	        e.preventDefault();
175	        onNavigate(item.href);
176	      }}
177	      className={`flex items-center gap-3 px-3 py-2 rounded-lg text-sm transition-colors ${
178	        active
179	          ? accent
180	            ? "bg-primary/10 text-primary font-semibold border-l-2 border-primary -ml-[2px] pl-[calc(0.75rem-2px)]"
181	            : "bg-primary/10 text-primary font-semibold"
182	          : "text-muted-foreground hover:bg-muted hover:text-foreground"
183	      }`}
184	    >
185	      <item.icon className="h-4 w-4 shrink-0" />
