64	function timeAgo(iso: string) {
65	  const diff = Date.now() - new Date(iso).getTime();
66	  const mins = Math.floor(diff / 60000);
67	  if (mins < 1) return "ką tik";
68	  if (mins < 60) return `prieš ${mins} min`;
69	  const hrs = Math.floor(mins / 60);
70	  if (hrs < 24) return `prieš ${hrs} val`;
71	  const days = Math.floor(hrs / 24);
72	  return `prieš ${days} d`;
