107	export function NotificationBell() {
108	  const { user, isSignedIn } = useUser();
109	  const { getToken } = useAuth();
110	  const { isAdmin, isOwner, isCoach } = useRole();
111	  const qc = useQueryClient();
112	  const [notifs, setNotifs] = useState<Notif[]>([]);
113	  const [adminNotifs, setAdminNotifs] = useState<Notif[]>([]);
114	  const [open, setOpen] = useState(false);
115	  const [location, setLocation] = useLocation();
116	  const intervalRef = useRef<ReturnType<typeof setInterval> | null>(null);
117	
118	  const userId = user?.id ?? null;
119	
120	  // Derive per-tab notification lists
121	  const playerNotifs = notifs.filter(n => getNotifAudience(n) === "player");
122	  const ownerNotifs = [
123	    ...notifs.filter(n => getNotifAudience(n) === "owner"),
124	    ...adminNotifs,
125	  ].sort((a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());
126	  const coachNotifs = notifs.filter(n => getNotifAudience(n) === "coach");
127	
128	  // Unread counts per tab and total
129	  const playerUnread = playerNotifs.filter(n => !n.read).length;
130	  const ownerUnread = ownerNotifs.filter(n => !n.read).length;
131	  const coachUnread = coachNotifs.filter(n => !n.read).length;
132	  const totalUnread = playerUnread + ownerUnread + coachUnread;
133	
134	  // Tabs — only show if user has more than just the player role
135	  const availableTabs: TabId[] = ["player"];
136	  if (isOwner) availableTabs.push("owner");
137	  if (isCoach) availableTabs.push("coach");
138	  const showTabs = availableTabs.length > 1;
139	
140	  const defaultTab = getDefaultTab(location, isOwner, isCoach);
141	  const [activeTab, setActiveTab] = useState<TabId>(defaultTab);
142	
143	  // Reset active tab each time the popover opens, based on current page
144	  useEffect(() => {
145	    if (open) setActiveTab(getDefaultTab(location, isOwner, isCoach));
146	  }, [open]); // eslint-disable-line react-hooks/exhaustive-deps
147	
148	  const tabNotifs = activeTab === "owner" ? ownerNotifs
149	    : activeTab === "coach" ? coachNotifs
150	    : playerNotifs;
151	
152	  const previewNotifs = tabNotifs.slice(0, 5);
153	  const tabUnread = activeTab === "owner" ? ownerUnread
154	    : activeTab === "coach" ? coachUnread
155	    : playerUnread;
156	
157	  const seeAllHref = activeTab === "owner" ? "/owner/notifications" : "/notifications";
158	
159	  const authFetch = useCallback(async (url: string, options?: RequestInit) => {
160	    const token = await getToken();
161	    const headers = new Headers(options?.headers);
162	    if (token) headers.set("Authorization", `Bearer ${token}`);
163	    return fetch(url, { ...options, headers, credentials: "include" });
164	  }, [getToken]);
165	
166	  const fetchNotifs = useCallback(async () => {
167	    if (!userId) return;
168	    try {
169	      const res = await authFetch(`/api/notifications`);
170	      if (res.ok) setNotifs(await res.json());
171	    } catch { /* silent */ }
172	  }, [userId, authFetch]);
173	
174	  const fetchAdminNotifs = useCallback(async () => {
175	    try {
176	      const res = await authFetch(`/api/admin/notifications`);
177	      if (res.ok) setAdminNotifs(await res.json());
178	    } catch { /* silent */ }
179	  }, [authFetch]);
180	
181	  useEffect(() => {
182	    if (!userId) return;
183	    // Defer first fetch 2 s so it doesn't compete with the home page's
184	    // critical queries (stats, courts, popular courts) during initial load.
185	    const delay = setTimeout(() => {
186	      fetchNotifs();
187	      if (isAdmin) fetchAdminNotifs();
188	    }, 2000);
189	    intervalRef.current = setInterval(() => {
190	      fetchNotifs();
191	      if (isAdmin) fetchAdminNotifs();
192	    }, 30000);
193	    return () => {
194	      clearTimeout(delay);
195	      if (intervalRef.current) clearInterval(intervalRef.current);
196	    };
197	  }, [userId, isAdmin, fetchNotifs, fetchAdminNotifs]);
198	
199	  async function markRead(notif: Notif) {
200	    const isAdminNotif = notif.userId === "__ADMIN__";
201	    const endpoint = isAdminNotif
202	      ? `/api/admin/notifications/${notif.id}/read`
203	      : `/api/notifications/${notif.id}/read`;
204	
205	    if (isAdminNotif) {
206	      setAdminNotifs(prev => prev.map(n => n.id === notif.id ? { ...n, read: true } : n));
207	    } else {
208	      setNotifs(prev => prev.map(n => n.id === notif.id ? { ...n, read: true } : n));
209	    }
210	    try {
