191	          and(eq(messagesTable.senderUserId, threadUserId), eq(messagesTable.recipientUserId, userId!)),
192	        ),
193	      ))
194	      .orderBy(messagesTable.createdAt);
195	    res.json(rows.map(formatMsg));
196	    return;
197	  }
198	
199	  // Default: only messages where caller is sender or recipient.
200	  const rows = await db
201	    .select()
202	    .from(messagesTable)
203	    .where(and(eq(messagesTable.courtId, courtId), or(eq(messagesTable.senderUserId, userId!), eq(messagesTable.recipientUserId, userId!))))
204	    .orderBy(messagesTable.createdAt);
