209	// POST /courts/:id/messages  — send a message (user→court or owner→user)
210	router.post("/courts/:id/messages", requireAuth, async (req, res): Promise<void> => {
211	  const courtId = Number(req.params.id);
212	  const { userId: senderUserId } = getAuth(req);
213	  const { body, threadUserId } = req.body ?? {};
214	  if (Number.isNaN(courtId) || !body) {
215	    res.status(400).json({ error: "Missing required fields" });
216	    return;
217	  }
218	
219	  // Resolve sender identity from Clerk — never trust client-supplied name/email.
220	  let senderName = "Vartotojas";
221	  let senderEmail = "";
222	  try {
223	    const clerkUser = await clerkClient.users.getUser(senderUserId!);
224	    senderName = [clerkUser.firstName, clerkUser.lastName].filter(Boolean).join(" ") || "Vartotojas";
225	    senderEmail = clerkUser.emailAddresses[0]?.emailAddress ?? "";
226	  } catch {
227	    // Clerk unavailable (e.g. no CLERK_SECRET_KEY in dev) — proceed with defaults.
228	  }
229	
230	  const [court] = await db.select().from(courtsTable).where(eq(courtsTable.id, courtId));
231	  if (!court) { res.status(404).json({ error: "Court not found" }); return; }
232	
233	  const [msgFacility] = await db.select({ ownerUserId: facilitiesTable.ownerUserId, email: facilitiesTable.email })
234	    .from(facilitiesTable)
235	    .where(eq(facilitiesTable.id, court.facilityId));
236	
237	  const isOwner = msgFacility?.ownerUserId === senderUserId;
238	
239	  // When owner replies, threadUserId tells us who they're replying to
240	  let recipientUserId: string | null = null;
241	  let recipientEmail: string | null = null;
242	
243	  if (isOwner && threadUserId) {
244	    // Owner replying to a user — find the user's email from prior messages
245	    const [prior] = await db
246	      .select()
247	      .from(messagesTable)
248	      .where(and(eq(messagesTable.courtId, courtId), eq(messagesTable.senderUserId, threadUserId)));
249	    recipientUserId = threadUserId;
250	    recipientEmail = prior?.senderEmail ?? null;
251	  } else {
252	    recipientUserId = msgFacility?.ownerUserId ?? null;
253	    recipientEmail = msgFacility?.email ?? null;
254	  }
255	
256	  const [message] = await db.insert(messagesTable).values({
257	    courtId,
258	    senderUserId: senderUserId!,
259	    senderName,
260	    senderEmail,
261	    recipientUserId,
262	    recipientEmail,
263	    subject: isOwner ? "Re: Žinutė nuo savininko" : "Žinutė kortui",
264	    body,
265	  }).returning();
266	
267	  // Fire notification for the recipient.
268	  //   - Player → Owner: link goes to /owner/messages so notification-bell's
269	  //     bridge routes the owner to their dedicated facility inbox.
270	  //   - Owner → Player: link deep-links the player into their DM inbox with
271	  //     court context, so they land on a messaging surface (not the court
272	  //     info page) and can reply via the unified /dm/send flow.
273	  if (recipientUserId) {
274	    const playerLink = `/messages?u=${senderUserId}&ctx=court&cid=${courtId}`;
275	    await db.insert(notificationsTable).values({
276	      userId: recipientUserId,
277	      type: "message",
278	      title: isOwner ? `Atsakymas nuo savininko — ${court.name}` : `Nauja žinutė nuo ${senderName}`,
279	      body: body.length > 100 ? body.slice(0, 97) + "…" : body,
280	      link: isOwner ? playerLink : "/owner/messages",
281	    }).catch(() => {});
282	  }
283	
284	  // Real-time: the "player side" of the thread is always the non-owner user.
285	  const playerId = isOwner ? (threadUserId ?? recipientUserId) : senderUserId;
286	  if (playerId) {
287	    const formatted = formatMsg(message);
288	    socketEmit(`facility_${courtId}_${playerId}`, "new_message", { type: "facility", message: formatted });
289	    if (recipientUserId) {
290	      socketEmit(`inbox_${recipientUserId}`, "unread_update", {});
291	    }
292	  }
293	
294	  res.status(201).json(formatMsg(message));
295	});
