674	// GET /coaches/me/facilities — facilities the coach is approved at, grouped
675	router.get("/coaches/me/facilities", requireCoach, async (req, res): Promise<void> => {
676	  const userId = getCurrentUserId(req)!;
677	  const [coach] = await db.select().from(coachesTable).where(eq(coachesTable.userId, userId));
678	  if (!coach) { res.json([]); return; }
679	
680	  const rows = await db
681	    .select({ court: courtsTable, facility: facilitiesTable })
682	    .from(courtCoachesTable)
683	    .innerJoin(courtsTable, eq(courtCoachesTable.courtId, courtsTable.id))
684	    .leftJoin(facilitiesTable, eq(courtsTable.facilityId, facilitiesTable.id))
685	    .where(eq(courtCoachesTable.coachId, coach.id));
686	
687	  // Group by facility (or by orphan court if no facility)
688	  type Group = {
689	    facilityId: number | null;
690	    facilityName: string | null;
691	    city: string | null;
692	    courts: Array<{ id: number; name: string }>;
693	  };
694	  const groups = new Map<string, Group>();
695	  for (const r of rows) {
696	    const key = r.facility?.id != null ? `f${r.facility.id}` : `c${r.court.id}`;
697	    if (!groups.has(key)) {
698	      groups.set(key, {
699	        facilityId: r.facility?.id ?? null,
700	        facilityName: r.facility?.name ?? null,
701	        city: r.facility?.city ?? null,
702	        courts: [],
703	      });
704	    }
705	    groups.get(key)!.courts.push({ id: r.court.id, name: r.court.name });
706	  }
707	  res.json(Array.from(groups.values()));
708	});
