749	router.post("/owner/respond-to-coach", requireOwner, async (req, res): Promise<void> => {
750	  const { invitationId, decision } = req.body ?? {};
751	  const id = Number(invitationId);
752	  if (!Number.isFinite(id)) { res.status(400).json({ error: "invitationId required" }); return; }
