151	    const rawPrice = requestData.pricePerHour;
152	    const pricePerHour =
153	      typeof rawPrice === "number" && Number.isFinite(rawPrice) && rawPrice >= 0
154	        ? Math.round(rawPrice)
155	        : typeof rawPrice === "string" && rawPrice.trim() !== "" && Number.isFinite(Number(rawPrice))
156	        ? Math.round(Number(rawPrice))
157	        : null;
158	    await db
159	      .insert(coachesTable)
160	      .values({
161	        userId,
162	        name: (requestData.name as string | undefined) ?? "Coach",
163	        email: (requestData.email as string | undefined) ?? "",
164	        bio: (requestData.bio as string | undefined) ?? null,
165	        photoUrl: (requestData.photoUrl as string | undefined) ?? null,
166	        pricePerHour,
167	        sports: sportsArr,
168	        availabilityDescription: (requestData.availabilityDescription as string | undefined) ?? null,
169	        phone: (requestData.phone as string | undefined) ?? null,
170	      })
171	      .onConflictDoUpdate({
172	        target: coachesTable.userId,
173	        set: {
174	          bio: (requestData.bio as string | undefined) ?? null,
175	          sports: sportsArr,
176	          pricePerHour,
177	          availabilityDescription: (requestData.availabilityDescription as string | undefined) ?? null,
178	          phone: (requestData.phone as string | undefined) ?? null,
179	        },
180	      });
181	  }
182	
183	  const [row] = await db
184	    .update(userRolesTable)
185	    .set({
186	      role: newRole,
187	      status: "active",
188	      pendingRole: null,
189	      requestData: null,
190	      rejectionReason: null,
191	      updatedAt: new Date(),
192	    })
193	    .where(eq(userRolesTable.userId, userId))
194	    .returning();
195	
196	  // Sync Clerk publicMetadata so JWT/session reflects the new role
197	  await clerkClient.users
198	    .updateUserMetadata(userId, { publicMetadata: { role: newRole } })
199	    .catch(() => {});
200	
201	  res.json(row);
202	});
