223	/** GET /admin/users — list all users with assigned roles + Clerk profile data (admin only) */
224	router.get("/admin/users", requireAdmin, async (_req, res): Promise<void> => {
225	  const rows = await db
226	    .select()
227	    .from(userRolesTable)
228	    .orderBy(userRolesTable.createdAt);
229	
230	  if (rows.length === 0) { res.json([]); return; }
231	
232	  // Enrich with Clerk user data (name, email, avatar). Chunk in batches of 100
233	  // because the Clerk SDK caps `limit` at 100 per request.
234	  const userIds = rows.map(r => r.userId);
235	  const clerkUsers: Record<string, { name: string | null; email: string | null; avatarUrl: string | null; lastSignInAt: number | null; clerkCreatedAt: number | null }> = {};
236	  const CHUNK = 100;
237	  for (let i = 0; i < userIds.length; i += CHUNK) {
238	    const chunk = userIds.slice(i, i + CHUNK);
239	    try {
240	      const clerkResp = await clerkClient.users.getUserList({ userId: chunk, limit: CHUNK });
241	      for (const cu of clerkResp.data) {
242	        const name = [cu.firstName, cu.lastName].filter(Boolean).join(" ") || null;
243	        const email = cu.emailAddresses?.[0]?.emailAddress ?? null;
244	        clerkUsers[cu.id] = {
245	          name,
246	          email,
247	          avatarUrl: cu.imageUrl ?? null,
248	          lastSignInAt: cu.lastSignInAt ?? null,
249	          clerkCreatedAt: cu.createdAt ?? null,
250	        };
251	      }
252	    } catch {
253	      // If a Clerk call fails, proceed without enrichment for that chunk
254	    }
255	  }
256	
257	  const profiles = userIds.length > 0
258	    ? await db
259	        .select({ userId: userProfilesTable.userId, stripeAccountStatus: userProfilesTable.stripeAccountStatus })
260	        .from(userProfilesTable)
261	        .where(inArray(userProfilesTable.userId, userIds))
262	    : [];
263	  const stripeMap = new Map(profiles.map(p => [p.userId, p.stripeAccountStatus ?? "not_connected"]));
264	
265	  const enriched = rows.map(r => ({
266	    ...r,
267	    name: clerkUsers[r.userId]?.name ?? null,
268	    email: clerkUsers[r.userId]?.email ?? null,
269	    avatarUrl: clerkUsers[r.userId]?.avatarUrl ?? null,
270	    lastSignInAt: clerkUsers[r.userId]?.lastSignInAt ?? null,
271	    clerkCreatedAt: clerkUsers[r.userId]?.clerkCreatedAt ?? null,
272	    stripeAccountStatus: stripeMap.get(r.userId) ?? "not_connected",
273	  }));
274	
275	  res.json(enriched);
276	});
