325	function ClerkQueryClientCacheInvalidator() {
326	  const { addListener } = useClerk();
327	  const qc = useQueryClient();
328	  const prevUserIdRef = useRef<string | null | undefined>(undefined);
329	
330	  useEffect(() => {
331	    const unsubscribe = addListener(({ user }) => {
332	      const userId = user?.id ?? null;
333	      if (
334	        prevUserIdRef.current !== undefined &&
335	        prevUserIdRef.current !== userId
336	      ) {
337	        qc.clear();
338	      }
339	      prevUserIdRef.current = userId;
340	    });
341	    return unsubscribe;
342	  }, [addListener, qc]);
343	
344	  return null;
345	}
