727	function ChatBubbleInner() {
728	  const { user } = useUser();
729	  const { getToken } = useAuth();
730	  const qc = useQueryClient();
731	  const [open, setOpen] = useState(false);
732	  const [tab, setTab] = useState<"people" | "games">("people");
733	  const [active, setActive] = useState<{ userId: string; userName: string; imageUrl?: string | null; ctxType?: string; ctxId?: number } | null>(null);
734	  const [activeGame, setActiveGame] = useState<MyGame | null>(null);
735	
736	  const { data: threads, isLoading: threadsLoading } = useQuery<Thread[]>({
737	    queryKey: ["dm-threads"],
738	    queryFn: () => customFetch<Thread[]>(`${API}/dm/threads`),
739	    enabled: !!user,
740	    staleTime: 60_000,
741	  });
742	
743	  const { data: myGames, isLoading: gamesLoading } = useQuery<MyGame[]>({
744	    queryKey: ["my-games-chat"],
745	    queryFn: () => customFetch<MyGame[]>(`${API}/games/my`),
746	    enabled: !!user && open,
747	    staleTime: 60_000,
748	  });
749	
750	  const { data: unread } = useQuery<{ count: number }>({
751	    queryKey: ["dm-unread"],
752	    queryFn: () => customFetch<{ count: number }>(`${API}/dm/unread-count`),
753	    enabled: !!user,
754	    staleTime: 60_000,
755	  });
756	
757	  // ── Socket lifecycle ────────────────────────────────────────────────────────
758	  // ChatBubble is always mounted for signed-in users, so it owns the socket
759	  // connection lifetime. Other pages (messages.tsx) reuse the same singleton.
760	  useEffect(() => {
761	    if (!user) return;
762	    const socket = getSocket();
763	
764	    (async () => {
765	      const token = await getToken();
766	      socket.auth = { token: token ?? "", userId: user.id };
767	      if (!socket.connected) socket.connect();
768	    })();
769	
770	    const onNewMessage = (data: { type: "dm" | "game" | "facility"; message: any }) => {
771	      if (data.type === "dm") {
772	        const msg = data.message as DM;
773	        const otherId = msg.senderUserId === user.id ? msg.recipientUserId : msg.senderUserId;
774	        // Append to the thread cache if it's already loaded (avoid duplicate ids)
775	        qc.setQueryData<DM[]>(["dm", otherId], (old) => {
776	          if (!old) return old;
777	          if (old.some((m) => m.id === msg.id)) return old;
778	          return [...old, msg];
779	        });
780	        // If incoming from someone else, refresh the thread list sidebar
781	        if (msg.senderUserId !== user.id) {
782	          qc.invalidateQueries({ queryKey: ["dm-threads"] });
783	        }
784	      } else if (data.type === "game") {
785	        const msg = data.message as GameChatMsg;
786	        qc.setQueryData<GameChatMsg[]>(["game-chat", msg.gameId], (old) => {
787	          if (!old) return old;
788	          if (old.some((m) => m.id === msg.id)) return old;
789	          return [...old, msg];
790	        });
791	      }
792	    };
793	
794	    const onUnreadUpdate = () => {
795	      qc.invalidateQueries({ queryKey: ["dm-unread"] });
796	      qc.invalidateQueries({ queryKey: ["dm-threads"] });
797	    };
798	
799	    socket.on("new_message", onNewMessage);
